    ('2e92aaeb-461a-4fef-aaa9-d594adf8f01d', 'cf7c1668e078161a426310944ab43e9c', $meta${"beat": "referee_controversy", "profile": {"age": 41, "bio": "SSSD's referee-controversy correspondent, Echo Rashidi makes a career of the leagues' most disputed decisions, and the officials hate her for it.", "race": "Human", "gender": "Female", "culture": "The officials' nemesis.", "appearance": "Forensic and fearless, unloved by officials.", "nationality": "Earthian", "personality": "Forensic, fearless, and combative.", "achievements": ["The leagues' leading voice on refereeing controversy"], "writing_style": "Investigative and provocative: refereeing under the microscope.", "playing_history": "Never played professionally.", "political_leaning": "Anti-establishment."}, "employer": "SSSD"}$meta$),
    ('2fd7d1d7-6689-4641-ba57-74e7b2961f63', '8166ca92e490137481a6d1fd921bd515', $meta${"profile": {"age": 47, "bio": "Luma Vasquez is a tactical chameleon who has built Solar City into a side with no fixed shape and no fear of any opponent. She studies, adapts, and out-thinks: the very model of the new, cosmopolitan game.", "race": "Orbital Colonist", "gender": "Female", "culture": "A colony native who believes the future belongs to the adaptable.", "appearance": "Elegant and watchful, dressed in clean colony lines, with the calm of someone who has seen every kind of football.", "nationality": "Orbital Colonist", "personality": "Cerebral, flexible, and quietly confident.", "achievements": ["Led the club's rise into genuine contention"], "playing_history": "A versatile midfielder who played across the colonies before management.", "political_leaning": "Frontier Coalition progressive.", "playing_philosophy": "Have no style of your own and you can borrow everyone else's. Balance first, then become whatever the match demands."}, "team_id": "solar-city", "game_model": {"tempo": "patient", "width": "balanced", "onLoss": "counterpress", "onRegain": "secure", "restShape": "3+2", "blockWidth": 40, "blockHeight": "mid", "blockLength": 34, "restDefence": 5, "buildUpShape": "3-2-5", "fullBackRole": "overlap", "pressTriggers": ["back_pass", "bad_touch"], "lineManagement": "measured", "counterpressSec": 5, "settledLineHeight": 32, "counterpressPlayers": 3}, "nationality": "Orbital Colonist"}$meta$),
