    ('33706ef7-d7f2-4879-a7a3-c7199c786a22', '731ce011ae5827c0f07ed26782a6092b', $meta${"type": "broadcaster", "reach": "inner_planets", "profile": {"bio": "ISS is the analysts' channel: tactical, measured, and proudly cerebral. Where GSN sells drama, ISS sells understanding, and the purists adore it for that.", "type": "Broadcaster (inner planets)", "owner": "An inner-worlds broadcasting consortium", "date_founded": "Founded to serve the rocky inner league.", "reporting_style": "Analytical, tactical, and sober: the chalkboard over the soundbite.", "political_leaning": "Compact-centrist; respectable and restrained."}}$meta$),
    ('3447683e-e518-4953-befd-455c14607f77', 'f6509bef85071a17b2a7aa70d0b1d034', $meta${"profile": {"badge": "A frozen heart-shaped glacier beneath a faded crown.", "history": "Pluto Frost are the fallen giants of the outer system: once the grandest club beyond the asteroid belt, now a proud, defensive side clinging to former glory. Their fans carry a grievance the size of a planet, and every win feels like a small reclamation of lost status.", "away_kit": "Ice-grey with a thin blue heart motif.", "home_kit": "Frost-white and pale blue with a faded-crown crest.", "third_kit": "Deep nitrogen-blue with a cracked-crown emblem.", "achievements": ["Most historic trophies of any Kuiper club"], "club_culture": "Proud, wounded, and defiantly nostalgic. The Demoted believe they belong among the elite and intend to climb back.", "date_founded": "Founded on Pluto in the first age of outer-system football, once a giant of the game and never quite over it.", "fans_nickname": "The Demoted", "number_of_fans": "Around 9 million proud, wounded supporters who remember the glory days.", "political_leaning": "Kuiper-restorationist: a club that wants its old standing back."}, "team_id": "pluto-frost", "league_id": "kuiper-belt"}$meta$),
    ('348fee19-bb82-416d-9574-31e79e8c4d58', 'b11ee2545b4340992ffd0826e4a51779', $meta${"profile": {"badge": "A spinning drill-bit boring into ore, sparks scattering.", "history": "Solar Miners drill for every inch of the pitch: a relentless high-pressing side that hounds opponents into the ground and never, ever lets up. Pure work-rate as a philosophy, the most exhausting team in the belt to face.", "away_kit": "Black with amber hazard striping.", "home_kit": "Hi-vis amber and black with a drill-tread pattern.", "third_kit": "Deep-shaft grey with an amber bit-line.", "achievements": ["Most pressures applied in the belt"], "club_culture": "Relentless, blue-collar, and proud of the graft. The Drillers believe effort is non-negotiable.", "date_founded": "Founded by the deep-extraction crews of a belt mining colony, who drill for every advantage.", "fans_nickname": "The Drillers", "number_of_fans": "Around 14 million relentless, blue-collar belt supporters.", "political_leaning": "Belt labour-militant: a miners' union club with a chip on its shoulder."}, "team_id": "solar-miners", "league_id": "outer-reaches"}$meta$),
    ('3be0cb11-0f11-4543-8cf1-967b90f7551f', '711e4e043be29fca779da5f7ad674c3e', $meta${"profile": {"age": 42, "bio": "Crystal Murai turns poverty into a weapon: her Geysers defend deep and patiently, then erupt forward the instant they win the ball. She has built a side that punches far above its modest budget.", "race": "Human (Enceladus-adapted)", "gender": "Female", "culture": "An underdog by birth who relishes humbling the rich.", "appearance": "Sharp and quick, paces the technical area waiting for the moment to spring.", "nationality": "Enceladean", "personality": "Patient, opportunistic, and fearless against bigger names.", "achievements": ["Masterminded famous counterattacking upsets"], "playing_history": "A quick counterattacking forward who played her whole career at small clubs.", "political_leaning": "Frontier-independent.", "playing_philosophy": "Absorb, wait, erupt. Let them have the ball until the moment it costs them everything."}, "team_id": "enceladus-geysers", "game_model": {"tempo": "vertical", "width": "wide", "onLoss": "recover", "onRegain": "counter", "restShape": "3+2", "blockWidth": 38, "blockHeight": "mid", "blockLength": 30, "restDefence": 5, "buildUpShape": "3-2-5", "fullBackRole": "overlap", "pressTriggers": ["always"], "lineManagement": "measured", "counterpressSec": 6, "settledLineHeight": 40, "counterpressPlayers": 4}, "nationality": "Enceladean"}$meta$),
