    ('3df78e76-abf4-4e1d-adda-9b385ecdadab', 'e6262373ce07b817052762c2fe905c29', $meta${"type": "broadcaster", "reach": "asteroid_belt", "profile": {"bio": "BBM is grassroots broadcasting from the asteroid belt: scrappy, community-run, and devoted to the unglamorous clubs the bigger networks ignore. The fans' own voice.", "type": "Broadcaster (asteroid belt)", "owner": "A belt workers' media co-operative", "date_founded": "Founded by belt fans for belt fans.", "reporting_style": "Grassroots, community-minded, and unpolished in the best way.", "political_leaning": "Belt-syndicalist; a co-operative through and through."}}$meta$),
    ('3f2851ea-37f4-4c8b-9aa2-6af64ccdff18', '33998c3798c587e1248addd53f7e2d4d', $meta${"profile": {"badge": "A stylised wave curling beneath a cracked ice ceiling, lit from below.", "history": "Europa Oceanic are the pioneers of fluid football, a side that moves like water, flowing around opponents in endless interchanging patterns. Raised in the weightless calm of the subsurface ocean, they play with a grace that makes possession look effortless and inevitable.", "away_kit": "Pale seafoam with blue trim and a rippling current motif.", "home_kit": "Deep ocean blue with flowing wave-line gradients down the body.", "third_kit": "Abyssal black with bioluminescent blue seams.", "achievements": ["Pioneers of the fluid interchange now studied league-wide"], "club_culture": "Graceful, fluid, and quietly confident. The Deep believe football should flow, never force.", "date_founded": "Founded by the deep-sea habitats beneath Europa's ice, where football was played in pressurised domes on the ocean floor.", "fans_nickname": "The Deep", "number_of_fans": "Around 33 million, drawn to the club's flowing, hypnotic football.", "political_leaning": "Frontier progressive, with the contemplative calm of the ocean depths."}, "team_id": "europa-oceanic", "league_id": "gas-giants"}$meta$),
