    ('480b2593-0aea-453e-a6e2-e4f9ae9cf076', 'f3d22cbf1656c7bf82715ff3166422c5', $meta${"profile": {"badge": "A glowing ingot struck on an anvil, sparks flying.", "history": "Psyche Metallics are built on raw physical power: an aggressive, muscular side that out-muscles and out-fights opponents into submission. On the great metal asteroid, strength is everything, and the Forgers have plenty.", "away_kit": "Bright steel-silver with orange seams.", "home_kit": "Molten orange and gunmetal with a forged-metal sheen.", "third_kit": "Blackened iron with ember flecks.", "achievements": ["Most duels and physical battles won in the belt"], "club_culture": "Hard, physical, and aggressive. The Forgers believe football is a test of strength first.", "date_founded": "Founded by the metal-extraction crews of Psyche, the great metallic asteroid.", "fans_nickname": "The Forgers", "number_of_fans": "Around 18 million, hard as the metal they mine.", "political_leaning": "Belt industrial-syndicalist: a foundry-workers' club with muscle."}, "team_id": "psyche-metallics", "league_id": "outer-reaches"}$meta$),
    ('483dd047-9a25-4ffb-aaeb-ebb6775380ad', 'c36ae4c580c34fd1d62de6ae5c79f1af', $meta${"profile": {"bio": "Marco Delgado is the last line and the calm voice behind it. A one-club man who turned down richer offers from the gas giants to stay at the Blue Marble, he organises the back line like a conductor and saves his theatrics for the rare moments that demand them.", "race": "Human", "gender": "Male", "culture": "Loyalist who measures himself in seasons, not contracts.", "species": "terran", "injuries": "Fully fit.", "appearance": "Broad-shouldered and unflappable, with a goalkeeper's economy of movement and a greying temple that makes him look older than he is.", "personality": "Steady, vocal, and reassuring: the dressing-room anchor.", "achievements": ["Long-serving first-choice keeper", "Club's record holder for consecutive clean sheets in a single run"], "political_leaning": "Quiet Compact voter; keeps his opinions in the dressing room."}, "team_id": "earth-united", "position": "GK", "nationality": "Earthian"}$meta$),
