    ('4cc2bc72-0149-4c80-9806-1381a5d276ee', '91b32f155d81103270169a148b08abaf', $meta${"profile": {"bio": "Flux Santos is the engine that lets Nakamura create: a selfless midfielder who does two players' running so the artist can breathe.", "race": "Human (Mars-adapted)", "gender": "Male", "culture": "The unsung runner.", "species": "terran", "injuries": "Fully fit.", "appearance": "Stocky and relentless, covers every blade of the narrow pitch.", "personality": "Selfless and indefatigable.", "achievements": ["Most distance covered in the squad"], "political_leaning": "Moderate Martian-nationalist."}, "team_id": "mars-athletic", "position": "MF", "nationality": "Martian"}$meta$),
    ('4d9570df-b28d-4857-9b27-b9b416af3846', '77eb020528935e11ac40085fddb38028', $meta${"profile": {"age": 56, "bio": "Caldera Osei is Martian football royalty: a manager of grand reputation who plays direct, dominant football and makes no apology for it. He believes in getting the ball forward and winning the second ball, and he has the trophies to argue the point.", "race": "Human (Mars-adapted)", "gender": "Male", "culture": "The proud custodian of the planet's grandest club.", "appearance": "Tall, silver-maned, and immaculately dressed, with the bearing of a man who expects to be obeyed.", "nationality": "Martian", "personality": "Imperious and exacting; carries himself like a head of state.", "achievements": ["Multiple major honours as player and manager"], "playing_history": "A commanding centre-forward in his playing days, a terror in the air.", "political_leaning": "Martian establishment to the core.", "playing_philosophy": "Get it forward, win it back higher, and overpower them. Subtlety is for clubs without our resources."}, "team_id": "olympus-mons", "game_model": {"tempo": "direct", "width": "wide", "onLoss": "counterpress", "onRegain": "counter", "restShape": "4+2", "blockWidth": 42, "blockHeight": "high", "blockLength": 34, "restDefence": 6, "buildUpShape": "4-2-4", "fullBackRole": "stay", "pressTriggers": ["bad_touch", "wide"], "lineManagement": "measured", "counterpressSec": 4, "settledLineHeight": 32, "counterpressPlayers": 3}, "nationality": "Martian"}$meta$),
    ('4de57e05-808f-4ea4-afa3-98a5cc53130d', 'e9241b9b17a32267b0f3c076d701894e', $meta${"profile": {"badge": "A silver runner mid-stride across a blazing solar disc, heat-lines trailing behind.", "history": "Mercury Runners are built on one thing: speed. The closest club to the sun plays the fastest football in the system, pressing opponents into mistakes and breaking before they can blink. They have never been the richest, but on a good day no one can live with them.", "away_kit": "Deep solar-flare orange fading to black, like the terminator line of their world.", "home_kit": "Bronze and white with a shimmering heat-haze pattern across the shoulders.", "third_kit": "Mirror-silver, designed to throw back the light and dazzle opponents.", "achievements": ["Holds the league's fastest goal from kickoff"], "club_culture": "Frantic, fearless, and proudly scrappy. The Sunchasers believe tempo is a weapon and rest is for the dead.", "date_founded": "Founded by shift-workers on the sun-scorched first colony, who played in the brief shadow of dawn.", "fans_nickname": "The Sunchasers", "number_of_fans": "Around 14 million, fierce and few, baked hard by their home star.", "political_leaning": "Frontier-independent. A hard outpost that resents being told anything by the comfortable inner worlds."}, "team_id": "mercury-runners", "league_id": "rocky-inner"}$meta$),
