    ('5077c6dc-81fa-4dfb-a3cc-9179d4750c8f', '041fd1748934302ead370bd75e7ece49', $meta${"profile": {"bio": "Dust Mensah is the veteran whose talent always outran his appetite for work, kept around for the games his reading of play can still win.", "race": "Android (Mercury)", "gender": "Male", "culture": "The cautionary veteran.", "species": "android", "injuries": "Fully fit, but slow between matches.", "appearance": "Heavy-legged and unbothered, the squad's resident pessimist.", "personality": "Laid-back to a fault; coasts.", "achievements": ["A title winner in a former life"], "political_leaning": "Cynical about everything."}, "team_id": "mars-athletic", "position": "DF", "nationality": "Martian"}$meta$),
    ('51ef20e0-5af5-415e-be8e-3f518a6e7312', '97df73ce27a1cb280ab31e7695cbd535', $meta${"profile": {"badge": "A silver wolf's head against a pale moon, ringed by frost.", "history": "Callisto Wolves play as a pack or not at all. Their coordinated, snapping press is the most synchronised in the league: eleven players moving as one organism, hunting the ball in relays until the prey makes a mistake. Individual stars are distrusted here; the collective is everything.", "away_kit": "Midnight blue with silver claw-marks raking down one side.", "home_kit": "Steel-grey and white with a frosted wolf-fur texture across the shoulders.", "third_kit": "Pale ice-white with a faint pawprint trail.", "achievements": ["Most coordinated team presses in the league"], "club_culture": "Communal, loyal, and fiercely collective. At Callisto, no one hunts alone.", "date_founded": "Founded by the ice-mining crews of Callisto, who hunted in packs against the cold and learned to play the same way.", "fans_nickname": "The Pack", "number_of_fans": "Around 20 million, a tight-knit, howling support that travels as one.", "political_leaning": "Frontier collectivist: a co-operative club in a co-operative colony."}, "team_id": "callisto-wolves", "league_id": "gas-giants"}$meta$),
    ('5bf46e26-9962-4b89-845a-3ce6fa5d8c29', 'a1616ef019a0b233d18ff134057ae8eb', $meta${"profile": {"badge": "An orange droplet falling through swirling haze, half-hidden.", "history": "Titan Methane are the system's enigma: a hardy, patient side raised in thick atmosphere who specialise in the unsettling, counterattacking ambush. Opponents say playing them is like grasping at smoke: nothing seems to happen, and then suddenly the ball is in the net.", "away_kit": "Smoke-grey with faint orange seams.", "home_kit": "Murky orange and brown with a swirling haze pattern that obscures the number.", "third_kit": "Deep methane-amber fading into shadow.", "achievements": ["Most goals scored in the final fifteen minutes"], "club_culture": "Patient, secretive, and quietly tough. The Haze reveal nothing and punish everything.", "date_founded": "Founded in the haze-shrouded settlements of Titan, where football is played half-glimpsed through orange murk.", "fans_nickname": "The Haze", "number_of_fans": "Around 21 million, secretive and loyal, hard to read as their home moon.", "political_leaning": "Frontier-independent, with the guarded reserve of an isolated moon."}, "team_id": "titan-methane", "league_id": "gas-giants"}$meta$),
    ('5ff32893-ab98-426c-9970-1ec261c708b7', '9377a8bfaf06e409e67640ec8be6bf72', $meta${"profile": {"bio": "Rush Sato is the gifted young forward the Storm are grooming behind Rivera: selfish, confident, and impatient for his moment.", "race": "Human (Jupiter-adapted)", "gender": "Male", "culture": "The heir apparent.", "species": "terran", "injuries": "Fully fit.", "appearance": "Lean and hungry, an academy striker with a star's swagger.", "personality": "Selfish and ambitious.", "achievements": ["Youth top scorer"], "political_leaning": "Indifferent."}, "team_id": "jupiter-titans", "position": "FW", "nationality": "Jovian"}$meta$),
    ('5ff91deb-1979-4051-9dad-88cb0c5cd107', '787b5ec87bec4220848bbeeb251ba625', $meta${"profile": {"badge": "A golden ringed planet haloed in light, encircled by a band of stars.", "history": "Saturn Rings play the most beautiful football in the gas giants: fluid movement, intricate passing, and a refusal to do anything ugly. Aristocratic and aesthetic, they would rather lose with grace than win without it, a creed that thrills neutrals and occasionally costs them.", "away_kit": "Pale gold with purple trim and a thin halo line.", "home_kit": "Royal purple and gold with a sweeping ring-band across the chest.", "third_kit": "Deep space-violet with a luminous golden ring.", "achievements": ["Most admired playing style in the outer leagues"], "club_culture": "Refined, aesthetic, and proud of its beautiful traditions. The Haloed value how you win almost as much as whether you win.", "date_founded": "Founded in the elegant ring-cities of Saturn, where football was always meant to be beautiful.", "fans_nickname": "The Haloed", "number_of_fans": "Around 36 million connoisseurs who prize a sweeping move over a scrappy win.", "political_leaning": "Saturnian old-aristocracy: cultured, conservative, and quietly grand."}, "team_id": "saturn-rings", "league_id": "gas-giants"}$meta$),
    ('60c74565-9f73-4e37-ae78-c462e612e442', '66aa2a96d11ff388d44cfff771354e7c', $meta${"profile": {"bio": "Lena Kovacs is the balance at the heart of the defence: neither reckless nor passive, simply, reliably correct. Okafor trusts her to start every move, and the team's rhythm begins at her feet.", "race": "Human", "gender": "Female", "culture": "A steadying influence on the younger defenders.", "species": "terran", "injuries": "Fully fit.", "appearance": "Medium build, watchful eyes, a centre-back who reads the game a half-second before it happens.", "personality": "Level-headed and consistent; rarely flustered.", "achievements": ["Voted players' player by her own dressing room"], "political_leaning": "Centrist; votes Compact but grumbles about it."}, "team_id": "earth-united", "position": "DF", "nationality": "Earthian"}$meta$),
    ('64e1a22e-7112-45bc-b5ab-f8869ca0d023', 'c2fc609c75fa9e0d2d9c08615996ad15', $meta${"profile": {"bio": "Pyro Okafor is the teenage striker with the colony dreaming again: fast, selfish, and desperate to be the next Quicksilver.", "race": "Human (Mercury-adapted)", "gender": "Male", "culture": "The next great hope.", "species": "terran", "injuries": "Fully fit.", "appearance": "Lean and hungry, sprints like the manager once did.", "personality": "Selfish and burning to prove himself.", "achievements": ["Youngest scorer in recent club memory"], "political_leaning": "Indifferent."}, "team_id": "mercury-runners", "position": "FW", "nationality": "Mercurian"}$meta$),
    ('671ef508-b0f9-4383-827f-480e14b3265e', 'd0cea3e9a36cb80b08e569b80f7bc9dd', $meta${"profile": {"bio": "Blaze Corsen is the launchpad for the Runners' breaks, a keeper who clears his lines before opponents have reorganised. Balanced and brave off his line.", "race": "Android (Mercury)", "gender": "Male", "culture": "The first link in the fast chain.", "species": "android", "injuries": "Fully fit.", "appearance": "Sharp and alert, a sweeper-keeper who starts every counter.", "personality": "Composed and proactive.", "achievements": ["Most assists by a goalkeeper in the league"], "political_leaning": "Frontier-independent."}, "team_id": "mercury-runners", "position": "GK", "nationality": "Mercurian"}$meta$),
    ('6a1856b2-a4a8-4f8a-bc83-a98026ae7ed5', '0a8fbdc770813757ce14d9055eb24c49', $meta${"profile": {"badge": "A green sprout breaking through cracked earth toward a rising sun.", "history": "Terra Nova are football's idealists: a club that believes in building, not buying. They throw their academy graduates into attacking, fearless football and accept the defeats that come with youth, trusting that the harvest will be worth it. Neutrals adore them; the establishment finds them naive.", "away_kit": "White with green trim and a single green seedling on the chest.", "home_kit": "Fresh leaf-green with white sleeves and a sprouting-seedling motif at the heart.", "third_kit": "Earthy brown-and-green, like soil ready to grow.", "achievements": ["Produces more top-flight players than any other academy", "Highest-scoring side in the league most seasons"], "club_culture": "Romantic, attacking, and patient with youth. Terra Nova would rather lose four-three with kids than win one-nil with mercenaries.", "date_founded": "A relatively young Earth club, founded on an idealistic charter to grow its own talent rather than buy it.", "fans_nickname": "The Greenshoots", "number_of_fans": "Around 26 million, young and hopeful, drawn by the club's romance.", "political_leaning": "Progressive idealist: a club that votes with its conscience and wears it proudly."}, "team_id": "terra-nova", "league_id": "rocky-inner"}$meta$),
    ('75000000-0000-0000-0000-000000000002', '106cc846a56728e776981e1c9a6bd965', $meta${"role": "assistant_manager", "profile": {"age": 41, "bio": "Nadia Voss came up through sports science on the lunar colonies before Okafor poached her to run Earth United's conditioning. Where the manager guards the soul of the team, Voss guards its body, and the two argue productively about almost everything.", "race": "Human (Lunar-born)", "gender": "Female", "culture": "Pragmatic moderniser inside a deeply traditional house.", "appearance": "Compact and restless, forever clutching a battered data-slate; the only person at Kingswood who jogs to the training pitches.", "nationality": "Earthborn", "personality": "Energetic, data-hungry, and cheerfully blunt: the dressing-room counterweight to Okafor's stillness.", "achievements": ["Built the conditioning program credited with the club's strong late-match record"], "playing_history": "Never played professionally; came to football through the laboratory, a fact she wears as a badge of honour.", "political_leaning": "Frontier-sympathetic: a colony kid who never quite bought the old-Earth establishment line.", "playing_philosophy": "A team that cannot run in the last ten minutes has no philosophy at all. Marries the club's patient style to ruthless late-game fitness."}, "team_id": "earth-united", "specialty": "fitness science", "nationality": "Earthborn"}$meta$),
    ('75000000-0000-0000-0000-000000000003', '0d73dc9344402f994e8b13160e2391b0', $meta${"role": "set_piece_coach", "profile": {"age": 40, "bio": "Aero Caldas is the cold tactician behind the Furnace's fury, the set-piece specialist who ensures all that aggression converts the corners and free-kicks the chaos earns.", "race": "Human (Venus-adapted)", "gender": "Male", "culture": "The cold edge to the club's heat.", "appearance": "Wiry and watchful, forever scribbling dead-ball routines in a battered notebook.", "nationality": "Venusian", "personality": "Calculating and precise; the calm inside the storm.", "achievements": ["Most set-piece goals in the league"], "playing_history": "A modest defender who found his calling in the details of dead balls.", "political_leaning": "Venusian hardline-militant.", "playing_philosophy": "Aggression wins set pieces; planning wins the goals from them."}, "team_id": "venus-volcanic", "specialty": "set-piece design", "nationality": "Venusian"}$meta$),
    ('75000000-0000-0000-0000-000000000005', '7ed8f9822036c4eeabda1d708295471a', $meta${"role": "assistant_manager", "profile": {"age": 44, "bio": "Redd Okafor drills the back line until they move as one organism. Kael trusts him completely with the club's defensive shape, which is to say the club's entire identity.", "race": "Human (Mars-adapted)", "gender": "Male", "culture": "The keeper of the club's defensive faith.", "appearance": "Squat and intense, with a whistle permanently around his neck and a clipboard that never leaves his hand.", "nationality": "Martian", "personality": "Obsessive about structure; treats a misplaced marking assignment as a crisis.", "achievements": ["Architect of the league's meanest defence"], "playing_history": "A journeyman defender who learned the trade the hard way.", "political_leaning": "Apolitical; the back four is his only nation.", "playing_philosophy": "There is no glory in defending, only necessity. So do it perfectly."}, "team_id": "mars-athletic", "specialty": "defensive structure", "nationality": "Martian"}$meta$),
    ('75000000-0000-0000-0000-000000000032', '536332d9dd1f27584b4dab3bf699418e', $meta${"role": "assistant_manager", "profile": {"age": 43, "bio": "Void Mensah teaches survivalist football: making do, adapting fast, and finding an edge where none should exist.", "race": "Human (Kuiper-adapted)", "gender": "Male", "culture": "The survivalist.", "appearance": "Lean and resourceful, can fix anything with nothing.", "nationality": "Trans-Neptunian", "personality": "Resourceful and unflappable.", "achievements": ["Built the side's adaptability"], "playing_history": "A frontier journeyman.", "political_leaning": "Kuiper-frontier anarchist.", "playing_philosophy": "Use what you have, however little. Resourcefulness is a tactic."}, "team_id": "scattered-disc", "specialty": "survivalist football", "nationality": "Trans-Neptunian"}$meta$),
    ('780818ae-9b2c-40d0-99d0-13eda26726c6', '89bae305443d90c41c780dbbdbbdc754', $meta${"profile": {"bio": "Apex Voss is a giant keeper who owns every cross that enters his area, fitting for the most aerial side in the league. Balanced and authoritative.", "race": "Human (Mars-adapted)", "gender": "Male", "culture": "The master of his box.", "species": "terran", "injuries": "Fully fit.", "appearance": "Towering and commanding, dominates his box like a landlord.", "personality": "Composed and dominant.", "achievements": ["Most claimed crosses in the league"], "political_leaning": "Martian establishment."}, "team_id": "olympus-mons", "position": "GK", "nationality": "Martian"}$meta$),
    ('80000000-0000-0000-0000-000000000001', '7e24ef4b693d2949024f79efb0d6bcbd', $meta${"profile": {"bio": "The Heat Box earns its name: visiting players describe legs of lead and lungs of fire by the hour mark. The Runners, raised on it, only get faster.", "sponsors": "Powered and named by the solar-harvest combines that keep the colony alive.", "date_built": "Carved into a shaded crater wall during the colony's first expansion.", "pitch_size": "Long and wide, built to give the Runners room to sprint.", "pitch_type": "Heat-resistant synthetic weave that stays playable as the temperature swings.", "stand_names": ["The Quicksilver Stand", "The Dawn End", "The Furnace"]}, "quality": "professional", "team_id": "mercury-runners", "location": "Mercury", "nickname": "The Heat Box"}$meta$),
    ('80000000-0000-0000-0000-000000000002', '7ced703535f6e1e1f8b466d618bd9a28', $meta${"profile": {"bio": "The Blue Marble is less a stadium than a cathedral to the old game. Opposition players speak of the hush before kickoff and the roar that follows a fifteen-pass move; the home crowd applauds the build-up, not just the goal. To play here is to be reminded that football was here first.", "sponsors": "Naming rights held by the Terran Orbital Authority; concourse partnerships with old-Earth heritage brands.", "date_built": "Rebuilt over the bones of the original ground; the current bowl dates to the early modern era.", "pitch_size": "Full regulation, kept generously wide to reward the club's patient build-up.", "pitch_type": "Living Earth-grass hybrid, grown under managed daylight: a deliberate, expensive nod to tradition in an age of synthetic surfaces.", "stand_names": ["The Meridian Stand (main)", "The Comet End", "The Continental Terrace", "The Founders' Gallery"]}, "quality": "legendary", "team_id": "earth-united", "location": "Earth", "nickname": "The Blue Marble"}$meta$),
    ('80000000-0000-0000-0000-000000000003', 'f6691f7d8236ce22e36942319bffc1c0', $meta${"profile": {"bio": "Pressure Cooker Stadium is exactly that: a sealed, sweltering bowl where the noise has nowhere to escape and neither do visiting teams. The home crowd treats intimidation as a civic duty.", "sponsors": "Backed by the atmospheric-processing combines that make the cities liveable.", "date_built": "A sealed pressure-dome arena, one of the oldest on Venus.", "pitch_size": "Compact and tight, deliberately cramped to make the press inescapable.", "pitch_type": "Hardy synthetic turf rated for the dome's heat and humidity.", "stand_names": ["The Eruption Stand", "The Pressure End", "The Sulphur Terrace"]}, "quality": "professional", "team_id": "venus-volcanic", "location": "Venus", "nickname": null}$meta$),
    ('80000000-0000-0000-0000-000000000004', '2f891e782f1cba39417b7dfd186d78dd', $meta${"profile": {"bio": "The World Park (The Greenhouse) is bright, open, and forgiving, a stage designed for young players to express themselves. The crowd cheers a brave through-ball as loudly as a goal.", "sponsors": "Backed by sustainable-agriculture concerns sympathetic to the club's ethos.", "date_built": "A modern, sunlit ground built with the academy at its centre.", "pitch_size": "Large and open, built to encourage the expansive, attacking game.", "pitch_type": "Real living grass under managed sunlight: the namesake greenhouse effect.", "stand_names": ["The Seedling Stand", "The Harvest End", "The Academy Terrace"]}, "quality": "professional", "team_id": "terra-nova", "location": "Earth", "nickname": "The Greenhouse"}$meta$),
    ('80000000-0000-0000-0000-000000000005', '3508248e38849623bd48dab2fbc7e46f', $meta${"profile": {"bio": "The Dust Bowl is one of the most hostile away days in the league: wind-scoured, cold, and packed with fans who treat every opposition pass as a personal affront. Visiting sides talk about the dust in their teeth long after the final whistle.", "sponsors": "Backed by the Martian mining consortia whose rigs ring the city.", "date_built": "Raised in the early colonial era and reinforced against the dust storms ever since.", "pitch_size": "Tight and compact, deliberately narrow to choke the space attackers crave.", "pitch_type": "Hardy red-tinted synthetic turf, the only surface that survives the grit.", "stand_names": ["The Anchor Stand", "The Storm End", "The Miners' Terrace"]}, "quality": "professional", "team_id": "mars-athletic", "location": "Mars", "nickname": "The Dust Bowl"}$meta$),
    ('80000000-0000-0000-0000-000000000006', '061ffcd9f381c9b05ac86697e18bd81c', $meta${"profile": {"bio": "Limeil Stadium (The Mountain) is one of the great venues of the system, a steep, looming bowl where the crowd seems to hang directly over the pitch. Few away sides leave with their dignity, let alone points.", "sponsors": "Adorned with the crests of Mars's oldest and richest houses.", "date_built": "A legendary old ground, expanded over generations into a cathedral on the slope.", "pitch_size": "Full size, with the highest crossbar tolerances in the league for the aerial game.", "pitch_type": "Pristine managed turf, kept immaculate as a point of pride.", "stand_names": ["The Summit Stand", "The Renn End", "The Highland Terrace", "The Caldera Gallery"]}, "quality": "legendary", "team_id": "olympus-mons", "location": "Mars", "nickname": "The Mountain"}$meta$),
    ('80000000-0000-0000-0000-000000000008', 'f255d615b2d8a5f172c4610daa2fe20c', $meta${"profile": {"bio": "Orbital Stadium (The Ring) wraps the pitch in a full circle of sound, the crowd suspended in the colony's spin. Visiting players speak of the strange, weightless thrill of playing among the stars.", "sponsors": "Backed by the great trading houses that pass through the colony's docks.", "date_built": "A legendary feat of orbital engineering, built into the colony's central ring.", "pitch_size": "Full regulation, with the colony's managed gravity kept honest by league inspectors.", "pitch_type": "Advanced engineered turf grown in the colony's agricultural rings.", "stand_names": ["The Ring Stand", "The Dock End", "The Habitat Tier", "The Mond Gallery"]}, "quality": "legendary", "team_id": "solar-city", "location": "Largest Orbital Colony", "nickname": "The Ring"}$meta$),
    ('80000000-0000-0000-0000-000000000010', 'a9fa8b84223e054927a9a4976324bc24', $meta${"profile": {"bio": "The Ice Bowl is an eerie, beautiful venue: a glowing dome beneath kilometres of ice and ocean, where the crowd's roar carries strangely through the water. Visiting players describe it as playing inside a dream.", "sponsors": "Backed by the subsurface habitat authorities and deep-ocean mining guilds.", "date_built": "Built within a vast pressurised dome on the Europan ocean floor.", "pitch_size": "Generously large, to let the fluid interchange breathe.", "pitch_type": "Pristine engineered turf grown under the dome's managed light.", "stand_names": ["The Cole Stand", "The Current End", "The Abyss Terrace", "The Ice Ceiling Gallery"]}, "quality": "professional", "team_id": "europa-oceanic", "location": "Europa", "nickname": "The Ice Bowl"}$meta$),
    ('80000000-0000-0000-0000-000000000011', 'b4473ad659fb6cf95cf9a14437e08776', $meta${"profile": {"bio": "Crater Fields (The Cradle) is a heavy, hard-working ground where the crowd appreciates a block as loudly as a goal. Away forwards leave frustrated and bruised.", "sponsors": "Backed by the Ganymede mining unions and core-extraction guilds.", "date_built": "Built on the great crater fields above the deepest mine shafts.", "pitch_size": "Compact, suited to the deep, narrow defensive banks.", "pitch_type": "Hardy synthetic turf rated for the moon's heavy gravity.", "stand_names": ["The Hale Stand", "The Shaft End", "The Union Terrace"]}, "quality": "professional", "team_id": "ganymede-united", "location": "Ganymede", "nickname": "The Cradle"}$meta$),
    ('80000000-0000-0000-0000-000000000012', 'd2f8d2069cf3a488c3b6b2904bdc05fb', $meta${"profile": {"bio": "The Howling Den is a wall of sound: the Pack's supporters howl in unison when the press is triggered, a noise that has unnerved far grander visitors into surrendering the ball.", "sponsors": "Backed by the Callisto ice-extraction co-operatives.", "date_built": "Built on the frozen plains where the first mining packs played.", "pitch_size": "Compact, to keep the pack tight and the prey cornered.", "pitch_type": "Insulated synthetic turf that holds heat against the moon's deep cold.", "stand_names": ["The Vane Stand", "The Den End", "The Frost Terrace"]}, "quality": "professional", "team_id": "callisto-wolves", "location": "Callisto", "nickname": "The Howling Den"}$meta$),
    ('80000000-0000-0000-0000-000000000013', '1a10e1aeb304afe9a0a34475c1e9afed', $meta${"profile": {"bio": "Cassini Colosseum (The Halo) is among the most beautiful venues in the system, a ringed bowl that glows gold at dusk. The crowd applauds a perfect passing move as warmly as a goal.", "sponsors": "Patronised by the ring-cities' cultured trading houses.", "date_built": "An elegant arena suspended within Saturn's inner rings.", "pitch_size": "Generously wide, to let the beautiful game breathe.", "pitch_type": "Immaculate managed turf, kept fast and true for crisp passing.", "stand_names": ["The Sand Stand", "The Halo End", "The Ring Gallery"]}, "quality": "professional", "team_id": "saturn-rings", "location": "Saturn Rings", "nickname": "The Halo"}$meta$),
    ('80000000-0000-0000-0000-000000000014', '238d1abe441d30826f0e6d7f69a99224', $meta${"profile": {"bio": "The Orange Haze is a strange, half-lit dome where the murky atmosphere seems to seep onto the pitch. Visiting players speak of losing track of the ball, and of the Haze's counterattacks materialising out of the gloom.", "sponsors": "Backed by the hydrocarbon-harvest combines that fuel the moon.", "date_built": "Built within a sealed dome against Titan's thick, cold atmosphere.", "pitch_size": "Standard, with deep space to launch the ambush.", "pitch_type": "Hardy synthetic turf rated for the dense, frigid air.", "stand_names": ["The Sturm Stand", "The Haze End", "The Hydrocarbon Terrace"]}, "quality": "professional", "team_id": "titan-methane", "location": "Titan", "nickname": "The Orange Haze"}$meta$),
    ('80000000-0000-0000-0000-000000000015', '1d8f08b8050efd8274a8b118396c7a66', $meta${"profile": {"bio": "The Spray is a tight, functional bowl where the small crowd erupts in unison with every breaking counter, a sudden roar that mirrors the geysers outside.", "sponsors": "Backed by the Enceladus research and water-harvest stations.", "date_built": "A functional ground built beside the geyser fields.", "pitch_size": "Standard, with deep space behind to launch the counter into.", "pitch_type": "Hardy synthetic turf rated for the moon's deep cold.", "stand_names": ["The Tarn Stand", "The Plume End", "The Spray Terrace"]}, "quality": "functional", "team_id": "enceladus-geysers", "location": "Enceladus", "nickname": "The Spray"}$meta$),
    ('80000000-0000-0000-0000-000000000016', 'e0e07548a52d9a2fa9923c3abe71f165', $meta${"profile": {"bio": "The Tilted Field disorients before kickoff: the stands lean, the sightlines are wrong, and the home side's lopsided football only deepens the confusion. Visitors rarely feel settled here.", "sponsors": "Backed by the eccentric independent guilds of the tilted world.", "date_built": "Built on the tilted polar plains, its stands set at deliberately odd angles.", "pitch_size": "Asymmetric within the rules: wider on one flank than the other, to the visitors' confusion.", "pitch_type": "Hardy synthetic turf rated for the long, strange Uranian seasons.", "stand_names": ["The Skew Stand", "The Tilt End", "The Sideways Terrace"]}, "quality": "professional", "team_id": "uranus-sidewinders", "location": "Uranus", "nickname": "The Tilted Field"}$meta$),
    ('80000000-0000-0000-0000-000000000017', 'deca6f6c9f12f21220a624eb2bc3acfb', $meta${"profile": {"bio": "The Rock is exactly that: a hard, cold, unforgiving ground where the old belt crowd appreciates a clearance as much as a goal. Visitors leave bruised and pointless.", "sponsors": "Backed by the dwarf-planet's mining consortia.", "date_built": "Carved into the Cerean surface during the first mining boom.", "pitch_size": "Compact, suited to the deep defensive block.", "pitch_type": "Hardy synthetic turf rated for low gravity.", "stand_names": ["The Hane Stand", "The Core End", "The Diggers' Terrace"]}, "quality": "functional", "team_id": "ceres-miners", "location": "Ceres", "nickname": "The Rock"}$meta$),
    ('80000000-0000-0000-0000-000000000019', 'a33d326d3666dcd57ff1909f5ec3e3b8', $meta${"profile": {"bio": "The Drifter is a modest, modular ground with a transient feel, fitting for a club that prides itself on never being pinned down. Away teams rarely know which Pallas will turn up.", "sponsors": "Backed by the roving prospector guilds.", "date_built": "A modular, relocatable ground assembled on the Pallas surface.", "pitch_size": "Standard, kept flexible to suit the shifting game plan.", "pitch_type": "Hardy synthetic turf rated for low gravity.", "stand_names": ["The Castan Stand", "The Drift End", "The Prospectors' Terrace"]}, "quality": "functional", "team_id": "pallas-wanderers", "location": "Pallas", "nickname": "The Drifter"}$meta$),
    ('80000000-0000-0000-0000-000000000020', 'b93c2128fc17d0adc50889b6928025e1', $meta${"profile": {"bio": "The Dark Pitch is a low, dim, claustrophobic bowl deep underground where visiting players speak of losing their bearings, and of never finding a gap in the Shades' defence.", "sponsors": "Backed by the warren's life-support and mining guilds.", "date_built": "Excavated deep beneath the Hygiean surface.", "pitch_size": "Compact and tight, perfect for a smothering block.", "pitch_type": "Hardy synthetic turf under managed tunnel-light.", "stand_names": ["The Vell Stand", "The Tunnel End", "The Warren Terrace"]}, "quality": "functional", "team_id": "hygiea-united", "location": "Hygiea", "nickname": "The Dark Pitch"}$meta$),
    ('80000000-0000-0000-0000-000000000022', '050955f9d30e0656cbe34c2cb57b00d9', $meta${"profile": {"bio": "The Temple is the belt's grandest civic venue: orderly, well-run, and quietly imposing. Visiting sides find a disciplined, knowledgeable crowd that punishes indiscipline with scorn.", "sponsors": "Backed by the Junonian civic authority and trade halls.", "date_built": "Built as a civic monument at the heart of Juno's main settlement.", "pitch_size": "Full regulation, immaculately maintained.", "pitch_type": "Well-kept synthetic turf, true and even.", "stand_names": ["The Vorn Stand", "The Civic End", "The Forum Terrace"]}, "quality": "professional", "team_id": "juno-city", "location": "Juno", "nickname": "The Temple"}$meta$),
    ('80000000-0000-0000-0000-000000000027', '101b7f136822c6e3a8caada522a1c781', $meta${"profile": {"bio": "The Outpost is the most distant venue in the leagues: cold, defiant, and proud of how far visitors must travel to lose there. Few away days are more dreaded.", "sponsors": "Backed by the remote outpost's survival co-operatives.", "date_built": "A frontier ground at the literal edge of settled space.", "pitch_size": "Standard, with deep space to launch the counter.", "pitch_type": "Basic frontier synthetic turf, hard-wearing.", "stand_names": ["The Calder Stand", "The Edge End", "The Outpost Terrace"]}, "quality": "frontier", "team_id": "eris-wanderers", "location": "Eris", "nickname": "The Outpost"}$meta$),
    ('80000000-0000-0000-0000-000000000030', '1c17f61542bef083580e2421b9a1d4ae', $meta${"profile": {"bio": "The Pit is a dim, brooding basin where the home crowd falls eerily silent before every set piece, and erupts when the Shades steal another goal from the gloom.", "sponsors": "Backed by the colony's mining and ritual guilds.", "date_built": "A frontier ground carved into a shadowed Orcian basin.", "pitch_size": "Compact, suited to the deep, direct block.", "pitch_type": "Basic frontier synthetic turf, hard-wearing.", "stand_names": ["The Vex Stand", "The Gate End", "The Shades' Terrace"]}, "quality": "frontier", "team_id": "orcus-athletic", "location": "Orcus", "nickname": "The Pit"}$meta$),
    ('8070c2a5-b1f8-4df5-8669-a7fb96b52eef', '4aefd96326ee922f2c005d06cd08aa66', $meta${"profile": {"badge": "A pickaxe crossed with a drill over a grey dwarf-planet disc.", "history": "Ceres Miners are the toughest, oldest club in the belt: a defensive, unyielding side that grinds opponents into the regolith. They concede little and complain less, the embodiment of belt grit.", "away_kit": "Dust-grey with brown trim.", "home_kit": "Earth-brown and slate with an ore-seam pattern across the chest.", "third_kit": "Deep-core black with a single ore-vein stripe.", "achievements": ["Most clean sheets in belt history"], "club_culture": "Old, hard, and proud. The Diggers measure worth in graft and longevity.", "date_founded": "The oldest club in the Asteroid Belt, founded by the first deep-core mining crews on the dwarf planet Ceres.", "fans_nickname": "The Diggers", "number_of_fans": "Around 23 million, the proud old guard of belt football.", "political_leaning": "Belt old-frontier: the conservative heart of belt labour."}, "team_id": "ceres-miners", "league_id": "outer-reaches"}$meta$),
    ('80d55360-2c53-4d2a-9fbe-cd10c833aab9', 'cd69646449b25bf0127933b455f02de0', $meta${"profile": {"badge": "A clenched iron fist rising from red soil, set against a black sky with two small moons.", "history": "Mars Athletic are the planet's grinders: a club built not on flair but on the refusal to be beaten. They concede grudgingly, counter ruthlessly, and have made a virtue of frustrating richer, prettier sides into the red dust. Martians love them for it.", "away_kit": "Charcoal black with thin red piping and a faint ridge-line of Olympus across the chest.", "home_kit": "Oxide-red shirt, black shorts, red socks: the colours of the planet itself.", "third_kit": "Pale dust-grey, worn for derby days against the other Martian sides.", "achievements": ["Best defensive record in the league across several seasons"], "club_culture": "Stubborn, defiant, and proudly unglamorous. Effort is the only currency that buys respect at the Dust Bowl.", "date_founded": "An early-colonial charter, founded by the first wave of Martian settlers who needed something to do between dust storms.", "fans_nickname": "The Red Wall", "number_of_fans": "Around 22 million hard-bitten Martians who travel in dust-caked convoys.", "political_leaning": "Martian-nationalist. The club has always carried the planet's chip-on-the-shoulder resentment of inner-system condescension."}, "team_id": "mars-athletic", "league_id": "rocky-inner"}$meta$),
    ('81000000-0000-0000-0000-000000000001', '23ff0547ee60d279ffedd56fea7dc10c', $meta${"profile": {"bio": "The Sunrunner Training Complex is an elite sprint laboratory disguised as a football ground. Everything here is measured in fractions of a second; the Runners' entire identity is forged on its tracks.", "sponsors": "Funded by the colony's pride as much as its solar-combine money.", "date_built": "A modern, climate-sealed complex, the club's single biggest investment."}, "quality": "elite", "team_id": "mercury-runners", "location": "Mercury"}$meta$),
    ('81000000-0000-0000-0000-000000000002', '16e7aaf96fe552f5c91dcb59c0bf8b83', $meta${"profile": {"bio": "The Academy at Kingswood is where the Earth United creed is pressed into the young: rondo before running, brain before brawn. Its graduates carry the club's passing gospel to every corner of the leagues, and rival scouts haunt its perimeter fences for the ones who get away.", "sponsors": "Funded through the club's heritage trust rather than corporate backing, a point of considerable institutional pride.", "date_built": "Established a generation ago on the wooded estate at Kingswood, outside the old capital."}, "quality": "elite", "team_id": "earth-united", "location": "Earth"}$meta$),
    ('81000000-0000-0000-0000-000000000016', '14294f6edef39eca3c09794558f1dfe8', $meta${"profile": {"bio": "The Sideways Athletic Institute drills the unconventional: overloads, switches, and lateral movement designed to pull defences out of shape. Orthodoxy is gently discouraged.", "sponsors": "Funded by the world's independent-minded guilds.", "date_built": "A professional institute built, naturally, at an angle."}, "quality": "professional", "team_id": "uranus-sidewinders", "location": "Uranus"}$meta$),
    ('81000000-0000-0000-0000-000000000018', '0fcf3097b1241334b72ed2b955967c8d', $meta${"profile": {"bio": "The Vesta Athletic Centre drills the timing and aerial judgement that low-gravity, direct football demands, a craft unique to the protoplanet.", "sponsors": "Funded by the Vestan survey guilds.", "date_built": "A standard complex on the crater rim."}, "quality": "standard", "team_id": "vesta", "location": "Vesta"}$meta$),
    ('81000000-0000-0000-0000-000000000019', 'b1d6b623137a6cb3d404fb73298cecec', $meta${"profile": {"bio": "The Nomad Training Grounds drill versatility above all: every player learns multiple roles, so the Drifters can reshape themselves match to match.", "sponsors": "Funded modestly by the prospector guilds.", "date_built": "A basic facility, deliberately lean and portable."}, "quality": "basic", "team_id": "pallas-wanderers", "location": "Pallas"}$meta$),
    ('81000000-0000-0000-0000-000000000023', '136787061ff0de1ef931176cb9803ee7', $meta${"profile": {"bio": "The Junction Academy drills organisation and transition above all: winning the ball, keeping the shape, and breaking fast. It is practical schooling for a practical club.", "sponsors": "Funded co-operatively by the haulage guilds.", "date_built": "A standard-grade facility wedged into the transit colony."}, "quality": "standard", "team_id": "beltway", "location": "Beltway Habitat"}$meta$),
    ('81000000-0000-0000-0000-000000000024', '5edad813cd78ccba0cc1386d9002c26b', $meta${"profile": {"bio": "The Extraction Athletic Campus drills work-rate above all. The Drillers' relentless press is built on conditioning so brutal that opponents simply cannot match it.", "sponsors": "Funded on a shoestring by the drilling crews.", "date_built": "A basic facility at the extraction camp."}, "quality": "basic", "team_id": "solar-miners", "location": "Solar Miners Habitat"}$meta$),
    ('81000000-0000-0000-0000-000000000025', 'e48ab0800f9e714252c7706337bca77b', $meta${"profile": {"bio": "The Frost Academy drills disciplined, defensive football: the pragmatic creed of a proud club rebuilding from reduced means toward the heights it once knew.", "sponsors": "Funded by Pluto's heritage institutions.", "date_built": "A standard complex, a step down from the club's grand past."}, "quality": "standard", "team_id": "pluto-frost", "location": "Pluto"}$meta$),
    ('81000000-0000-0000-0000-000000000029', 'a6d718c07c29f1a3448d9e73f70ac139', $meta${"profile": {"bio": "The Creation Academy drills technique, vision, and youth above all. The Makers grow their own creators, since they cannot afford to buy them.", "sponsors": "Funded communally by the settlement.", "date_built": "A basic academy the community treasures."}, "quality": "basic", "team_id": "makemake", "location": "Makemake"}$meta$),
    ('81000000-0000-0000-0000-000000000031', '37ac6336d5c74af7b64e5404af746f94', $meta${"profile": {"bio": "The Perihelion Training Ground drills patience and defensive discipline above all. The Mariners are taught that the right moment always comes to those who wait for it.", "sponsors": "Funded modestly by the remote colony.", "date_built": "A basic facility on the far frontier."}, "quality": "basic", "team_id": "sedna-mariners", "location": "Sedna"}$meta$),
    ('81000000-0000-0000-0000-000000000032', 'c910730a03bfd8f67c502587e915dcaf', $meta${"profile": {"bio": "The Scatter Academy drills survivalist football: adaptability, resilience, and making do with whatever the harsh frontier provides.", "sponsors": "Funded by the outposts' survival co-operatives.", "date_built": "A basic facility scraped together at the frontier."}, "quality": "basic", "team_id": "scattered-disc", "location": "Outer Kuiper Belt"}$meta$),
    ('835459df-aff5-4815-a24f-e488283b48ce', 'a0026d5f711b5fe60b93cac6d5d10941', $meta${"corps": "IEOB", "profile": {"age": 45, "bio": "A measured Callistian referee, Pollux Kowalski reads the synchronised pressing sides of the gas giants better than most.", "race": "Human (Callisto-adapted)", "gender": "Male", "culture": "The reader of the press.", "appearance": "Steady and communal, attuned to team play.", "nationality": "Callistian", "personality": "Steady, perceptive, and fair.", "achievements": ["Specialist in high-pressing fixtures"], "officiating_style": "Anticipatory: reads pressing patterns early.", "political_leaning": "Frontier collectivist."}, "homeworld": "Callisto"}$meta$),
    ('8385077c-d0c4-4e9f-88a1-d88ffa05974f', 'bae0b67d35fb32ebcf9640afb727dff5', $meta${"corps": "IEOB", "profile": {"age": 50, "bio": "A stern Martian referee, Aldebaran Singh brings the discipline of the red planet to every match he officiates.", "race": "Human (Mars-adapted)", "gender": "Male", "culture": "The disciplinarian.", "appearance": "Imposing and stoic, unmoved by protest.", "nationality": "Martian", "personality": "Stoic, firm, and unflappable.", "achievements": ["Trusted with the biggest Martian derbies"], "officiating_style": "Firm and disciplined: keeps tight control.", "political_leaning": "Martian-nationalist."}, "homeworld": "Mars"}$meta$),
    ('856fc150-1aea-493a-8a76-88644c32781d', '6b9cfd41cf8191c421fea49d166475f6', $meta${"profile": {"bio": "Vela Cruz does the selfless work that lets Osei create and Reyes hunt, the unfussy passer who keeps the tempo lethal.", "race": "Android (Mercury)", "gender": "Female", "culture": "The quiet connector.", "species": "android", "injuries": "Fully fit.", "appearance": "Tidy and team-minded, the glue of the midfield three.", "personality": "Selfless and consistent.", "achievements": ["Highest pass volume in the side"], "political_leaning": "Frontier-independent."}, "team_id": "mercury-runners", "position": "MF", "nationality": "Mercurian"}$meta$),
    ('859325f0-f773-445b-8aa0-8660bb58d11e', '5a05f0e0b2e9a69cdd29642b1e751e1f', $meta${"profile": {"age": 47, "bio": "Genesis Solano is a possession purist who conjures creative, patient football from a tiny budget. Her Makers keep the ball and craft chances from nothing: an act of faith and skill in equal measure.", "race": "Human (Kuiper-adapted)", "gender": "Female", "culture": "A believer in creation over expenditure.", "appearance": "Calm and devout, watches her side weave patterns with a quiet smile.", "nationality": "Makemakean", "personality": "Patient, creative, and quietly devout.", "achievements": ["Built the Kuiper's most creative side on the smallest budget"], "playing_history": "A playmaker who orchestrated games at small clubs.", "political_leaning": "Kuiper-communalist.", "playing_philosophy": "Keep the ball and create. With patience and craft, something always appears."}, "team_id": "makemake", "game_model": {"tempo": "patient", "width": "wide", "onLoss": "counterpress", "onRegain": "secure", "restShape": "2+3", "blockWidth": 38, "blockHeight": "mid", "blockLength": 32, "restDefence": 5, "buildUpShape": "3-2-5", "fullBackRole": "overlap", "pressTriggers": ["back_pass", "bad_touch"], "lineManagement": "measured", "counterpressSec": 5, "settledLineHeight": 47, "counterpressPlayers": 3}, "nationality": "Makemakean"}$meta$),
    ('868d19ac-08b7-4b2a-8352-788d4902892a', '7616783954f4d9cc1786b76fae8ac02b', $meta${"corps": "IEOB", "profile": {"age": 48, "bio": "A patient Hygieian referee, Phecda Okello keeps control of the dark, defensive matches of his subterranean home.", "race": "Human (Belt-adapted)", "gender": "Male", "culture": "The quiet observer.", "appearance": "Quiet and watchful, comfortable in the gloom.", "nationality": "Hygieian", "personality": "Quiet, patient, and observant.", "achievements": ["Specialist in low-scoring, defensive fixtures"], "officiating_style": "Patient and watchful: control without fuss.", "political_leaning": "Belt-isolationist."}, "homeworld": "Hygiea"}$meta$),
    ('895b480e-1410-4538-b604-b57fe7bafd92', '8c20158b8a8cef9a74bd79c691caefb7', $meta${"beat": "statistics", "profile": {"age": 34, "bio": "GSN's statistics correspondent, Atlas Kim turns the leagues' raw numbers into the stories behind the stories.", "race": "Human", "gender": "Male", "culture": "The stats reporter.", "appearance": "Quiet and numerate, surrounded by spreadsheets.", "nationality": "Earthian", "personality": "Quiet, rigorous, and insightful.", "achievements": ["Built the leagues' leading statistical column"], "writing_style": "Numbers-led: the data desk's voice.", "playing_history": "Never played professionally.", "political_leaning": "Frontier technocrat."}, "employer": "GSN"}$meta$),
    ('8e1fc1c3-23c7-4c83-964b-7cc6c2671bcd', '77b467c920f08bae1bb7c57bc5b69e8e', $meta${"profile": {"badge": "A clenched titan's fist wreathed in storm-cloud, the Great Red Spot raging behind it.", "history": "Jupiter Titans are the great power of the gas-giant game: vast, wealthy, and physically overwhelming. Built on raw strength and a fearsome defensive line, they bully opponents into submission and expect to win every trophy in sight. Loved on Jupiter, feared and envied everywhere else.", "away_kit": "Deep charcoal with orange lightning forking down the sides.", "home_kit": "Burnt orange and storm-grey with a swirling tempest pattern across the chest.", "third_kit": "Cream and rust, evoking the planet's banded clouds.", "achievements": ["Most league titles in Gas/Ice Giants League history", "Record for fewest goals conceded in a season"], "club_culture": "Powerful, entitled, and ruthlessly winning. The Storm believe dominance is their birthright.", "date_founded": "One of the oldest and grandest charters of the outer worlds, founded in the storm-cities of Jupiter at the dawn of gas-giant football.", "fans_nickname": "The Storm", "number_of_fans": "Around 60 million, a colossal, demanding following spread across the Jovian moons.", "political_leaning": "Jovian establishment superpower: the club of the outer system's old money and political muscle."}, "team_id": "jupiter-titans", "league_id": "gas-giants"}$meta$),
    ('8f64071d-8079-467f-8230-56470587b802', '146e9f0fede2f7b997d474ae9700053d', $meta${"profile": {"badge": "A planet tipped fully on its side, a serpentine sidewinder coiled around it.", "history": "Uranus Sidewinders are the league's wild card. Raised on a world that spins on its side, they play unpredictable, lopsided, attacking football that bewilders opponents and, frequently, themselves. On their day they are dazzling; on their off day, chaos. And no one, least of all them, can predict which it will be.", "away_kit": "Pale ice-cyan with crooked, sideways striping.", "home_kit": "Turquoise and white with a diagonal, off-kilter slash across the body.", "third_kit": "Deep teal with a tilted, asymmetric crest.", "achievements": ["Most goals from unconventional positions in the league"], "club_culture": "Eccentric, attacking, and gloriously unpredictable. The Tilt would rather entertain than be safe.", "date_founded": "Founded on tilted, sideways-spinning Uranus, where nothing is quite oriented the way it should be, including the football.", "fans_nickname": "The Tilt", "number_of_fans": "Around 19 million, eccentric and devoted, who never know what they'll get.", "political_leaning": "Frontier-eccentric: contrarian and allergic to convention."}, "team_id": "uranus-sidewinders", "league_id": "gas-giants"}$meta$),
    ('8f9d44af-f207-4cf1-bd43-b448dcaa5ab0', '1d90409d7138b2e52995c81f495abb8c', $meta${"era": "retired_player", "profile": {"age": 52, "bio": "A revered retired Earthian midfielder turned the system's most quoted tactical pundit, Rex Valorum dissects matches with the gravity of a man who won everything.", "race": "Human", "gender": "Male", "culture": "The game's grand old voice.", "appearance": "Silver-suited and authoritative, the elder statesman of the studio.", "nationality": "Earthian", "personality": "Authoritative, measured, and quietly vain.", "achievements": ["The system's most-watched tactical analyst"], "playing_history": "A decorated central midfielder of the old order.", "commentary_style": "Tactical and magisterial: pronounces verdicts as if from on high.", "political_leaning": "Compact establishment."}, "homeworld": "Earth", "specialty": "tactics"}$meta$),
    ('90bfe47b-183e-4859-a47b-4a62223b8e10', '12f0b25d33afc390ecc584dcf54cc796', $meta${"profile": {"age": 44, "bio": "Solano Vex is pace incarnate: a former flying winger who now demands her teams play the way she ran. Her high-pressing system is exhausting to play against and, frankly, to play in, but it has embarrassed far grander clubs.", "race": "Human (Mercury-adapted)", "gender": "Female", "culture": "A Mercurian who believes her hard little world is owed nothing and fears no one.", "appearance": "Compact and electric, never still on the touchline, eyes hidden behind a permanent visor against the glare.", "nationality": "Mercurian", "personality": "Restless, intense, and impatient with anything slow.", "achievements": ["Masterminded several famous cup upsets of inner-system giants"], "playing_history": "A blistering winger for the Runners in her day, briefly the quickest in the league.", "political_leaning": "Frontier-independent to her bones.", "playing_philosophy": "Win the ball high, score before they breathe, never let the game slow down."}, "team_id": "mercury-runners", "game_model": {"tempo": "vertical", "width": "wide", "onLoss": "counterpress", "onRegain": "counter", "restShape": "3+1", "blockWidth": 38, "blockHeight": "high", "blockLength": 30, "restDefence": 4, "buildUpShape": "3-1-6", "fullBackRole": "overlap", "pressTriggers": ["always"], "lineManagement": "aggressive", "counterpressSec": 6, "settledLineHeight": 40, "counterpressPlayers": 4}, "nationality": "Mercurian"}$meta$),
    ('919fa0de-3e6f-4789-a7d5-0e6d28fe3128', '3b440d96e42460cfc3c8b674d8470502', $meta${"profile": {"badge": "A shielded lantern glowing in a black tunnel mouth.", "history": "Hygiea United are masters of the dark arts of defending: a subterranean side built on impregnable structure who smother opponents in the gloom of The Dark Pitch and dare them to find a way through.", "away_kit": "Slate grey with green trim.", "home_kit": "Charcoal and deep green with a faint tunnel-light glow on the chest.", "third_kit": "Near-black with a single lantern emblem.", "achievements": ["Fewest goals conceded in the belt across multiple seasons"], "club_culture": "Insular, disciplined, and defensively obsessive. The Shades trust the structure above all.", "date_founded": "Founded in the sealed subterranean warrens of Hygiea, where football is played far below the surface.", "fans_nickname": "The Shades", "number_of_fans": "Around 13 million, dwelling in the dark and proud of it.", "political_leaning": "Belt-isolationist: a closed, self-sufficient warren that keeps the system at arm's length."}, "team_id": "hygiea-united", "league_id": "outer-reaches"}$meta$),
    ('94e04f53-1986-48cc-9b81-81ca033828bc', 'a8c98d380090d029ccbd5ab7ec093011', $meta${"profile": {"age": 45, "bio": "Dominic Harrow is a true believer, a coach who would rather develop a teenager than sign a star. His attacking, offensive football is thrilling and fragile in equal measure, and he wouldn't have it any other way.", "race": "Human", "gender": "Male", "culture": "A teacher first and a manager second.", "appearance": "Boyish and animated, in tracksuit more often than a suit, always closest to the youngest players.", "nationality": "Earthian", "personality": "Optimistic, nurturing, and stubbornly principled.", "achievements": ["Developed a generation of stars now scattered across the leagues"], "playing_history": "A modest attacking midfielder whose career was ended early by injury, turning him to coaching young.", "political_leaning": "Progressive idealist.", "playing_philosophy": "Attack, express, and trust the kids. Goals conceded are the price of goals scored."}, "team_id": "terra-nova", "game_model": {"tempo": "vertical", "width": "wide", "onLoss": "counterpress", "onRegain": "counter", "restShape": "3+1", "blockWidth": 44, "blockHeight": "mid", "blockLength": 36, "restDefence": 4, "buildUpShape": "3-1-6", "fullBackRole": "overlap", "pressTriggers": ["back_pass", "bad_touch"], "lineManagement": "aggressive", "counterpressSec": 5, "settledLineHeight": 42, "counterpressPlayers": 2}, "nationality": "Earthian"}$meta$),
    ('9526dc99-4d5f-4b22-9b87-6fc2c7370187', '93f168b9f2eae37a38957c4027491973', $meta${"profile": {"bio": "Helena Papadopoulos is the academy's brightest defensive prospect, fast-tracked into the squad ahead of schedule. Balanced beyond her years, she is being eased in carefully: the club has waited generations for a centre-back like her and refuses to rush it.", "race": "Ignid (Venus)", "gender": "Female", "culture": "The future of the back line.", "species": "ignid", "injuries": "Fully fit.", "appearance": "Coltish and quick, a teenager's lankiness not yet grown into power.", "personality": "Composed for her age; quietly determined.", "achievements": ["Kingswood academy player of her year"], "political_leaning": "Too young to have decided."}, "team_id": "earth-united", "position": "DF", "nationality": "Earthian"}$meta$),
    ('95835310-6a15-4bd7-a77b-597bed42226a', 'd0a41deab6fb0d85136dd032fa4a5bdd', $meta${"profile": {"bio": "Rift Osei is the outlet on the break, a forward who carries the ball seventy metres in a heartbeat when Mars Athletic turn defence into attack.", "race": "Human (Mars-adapted)", "gender": "Male", "culture": "The counterattack made flesh.", "species": "terran", "injuries": "Fully fit.", "appearance": "Balanced and quick, comfortable on either flank.", "personality": "Composed and dangerous in transition.", "achievements": ["Several long-range counter goals"], "political_leaning": "Moderate."}, "team_id": "mars-athletic", "position": "FW", "nationality": "Martian"}$meta$),
    ('968027fb-18fb-451d-ad3b-1163fc6fd170', 'c9fefa4dd3fe4fe5c0fc2dd0ea6d5055', $meta${"corps": "IEOB", "profile": {"age": 46, "bio": "A calm Europan referee, Arcturus Volkov is ideally suited to the fluid, patient possession sides of the outer system.", "race": "Human (Europa-adapted)", "gender": "Male", "culture": "The possession official.", "appearance": "Smooth and unhurried, flows with possession football.", "nationality": "Europan", "personality": "Calm, fluid, and patient.", "achievements": ["Favoured for possession-heavy fixtures"], "officiating_style": "Flow-friendly: rarely interrupts a passing move.", "political_leaning": "Frontier progressive."}, "homeworld": "Europa"}$meta$),
    ('98fda07a-82ab-4e70-8b5b-169b389bbb92', '7143319183d342664c4e400b9a7d5756', $meta${"era": "retired_player", "profile": {"age": 39, "bio": "A fiery retired Venusian forward, Echo Ferrara specialises in form analysis, calling slumps and surges before anyone else.", "race": "Human (Venus-adapted)", "gender": "Female", "culture": "The form-watcher.", "appearance": "Sharp and intense, never misses a dip in a player's form.", "nationality": "Venusian", "personality": "Intense, blunt, and uncannily perceptive.", "achievements": ["Renowned for predicting players' slumps"], "playing_history": "An aggressive former forward.", "commentary_style": "Forensic and unsparing: tracks form like a hawk.", "political_leaning": "Venusian hardline."}, "homeworld": "Venus", "specialty": "form_analysis"}$meta$),
