    ('9aa04b40-c5d5-4364-b03a-190eac17c4b1', 'd6171711cfbea7f8fc528a73c72cab55', $meta${"corps": "IEOB", "profile": {"age": 43, "bio": "A serene Sednan referee, Bellatrix Nkosi is unmatched at officiating the glacial, ultra-patient matches of the far Kuiper.", "race": "Human (Kuiper-adapted)", "gender": "Female", "culture": "The patient one.", "appearance": "Serene and unhurried, the most patient whistle of all.", "nationality": "Sednan", "personality": "Serene, patient, and immovable.", "achievements": ["Specialist in the slowest, most patient fixtures"], "officiating_style": "Endlessly patient: never rushes a decision.", "political_leaning": "Kuiper-isolationist."}, "homeworld": "Sedna"}$meta$),
    ('9b22d44e-b5be-400e-b941-d59cd38290ff', '4274352ca681c7e6512e403433153299', $meta${"beat": "gas-giants", "profile": {"age": 41, "bio": "GSN's gas-giants correspondent, Kael Nkosi covers the outer-system powerhouses with insider warmth.", "race": "Human (Jupiter-adapted)", "gender": "Male", "culture": "The gas-giants man.", "appearance": "Broad and genial, at home in any gas-giant press box.", "nationality": "Jovian", "personality": "Genial, connected, and shrewd.", "achievements": ["The definitive voice on gas-giant football"], "writing_style": "Warm and well-sourced: close to the big outer clubs.", "playing_history": "Never played professionally.", "political_leaning": "Jovian establishment."}, "employer": "GSN"}$meta$),
    ('9e8e9f2c-a728-43fd-ba2c-567eb15c8077', '1eb581628b94e6fdfa4755aa139307ea', $meta${"corps": "IEOB", "profile": {"age": 50, "bio": "A hardy Ganymedean referee, Betelgeuse Park thrives in the grinding, defensive matches of the working-world clubs.", "race": "Human (Ganymede-adapted)", "gender": "Male", "culture": "The battler's referee.", "appearance": "Sturdy and unmoved, at home in physical battles.", "nationality": "Ganymedean", "personality": "Sturdy, fair, and unmoved.", "achievements": ["Specialist in physical, defensive fixtures"], "officiating_style": "Lets them battle: high tolerance for the physical.", "political_leaning": "Frontier labour-collectivist."}, "homeworld": "Ganymede"}$meta$),
    ('9f9cd91e-863f-4bb2-84a4-b421a0d1c707', 'afa5e2a57d4ac929040d7c07a6f220b8', $meta${"profile": {"badge": "Crossed mining picks over a great grey moon, ringed by iron.", "history": "Ganymede United are football's labourers: a club founded by miners and built on endurance, organisation, and refusal to yield. They defend in deep, disciplined banks and grind opponents down with sheer unbreakable solidity. It is unglamorous, and they are proud of that.", "away_kit": "Ore-brown with grey trim and a thin seam-line of silver.", "home_kit": "Iron grey and black with a riveted-plate texture across the chest.", "third_kit": "Deep core-black with a single grey strike-line.", "achievements": ["Most clean sheets in the league across multiple seasons"], "club_culture": "Working-class, solid, and stubbornly collective. The Miners value graft over glamour and solidarity over stars.", "date_founded": "Founded by the deep-core mining unions of Ganymede, the system's largest moon, on a charter of solidarity and graft.", "fans_nickname": "The Miners", "number_of_fans": "Around 34 million working-class supporters who treat the club as their own.", "political_leaning": "Frontier labour-collectivist: a union club to its bones."}, "team_id": "ganymede-united", "league_id": "gas-giants"}$meta$),
    ('a13768c1-9480-402f-95ad-ea4906de933a', '8c3741d8917d7f34591f54e1ba8fa9ff', $meta${"profile": {"badge": "A deep canyon cleaving a red plateau, a thin river of silver at its base.", "history": "Valles Mariners are the thinking person's Martian club: patient, technical, and devoted to keeping the ball. While their rivals bludgeon, the Canyoneers pass, building moves as slowly and inexorably as their canyon was carved. It is football as geology.", "away_kit": "Sandstone cream with brown trim and a thin silver rift line.", "home_kit": "Burnt-orange and brown with a canyon-stratum banding across the shirt.", "third_kit": "Deep canyon-shadow purple, worn under floodlights.", "achievements": ["Highest average possession in the league, season after season"], "club_culture": "Cerebral, patient, and quietly superior. The Canyoneers believe possession is a kind of meditation.", "date_founded": "Founded by the canyon-dwelling communities of the great Martian rift, who played their first matches on the trench floor.", "fans_nickname": "The Canyoneers", "number_of_fans": "Around 28 million patient Martians who appreciate a well-worked goal over a scrambled one.", "political_leaning": "Martian regionalist-technocrat: proud of their rift, sceptical of grand planetary politics."}, "team_id": "valles-mariners", "league_id": "rocky-inner"}$meta$),
    ('a1b3dc06-b354-4682-b947-f01601b4c9a3', 'dce36c1e8085d926f6acbfbaa4c66b00', $meta${"profile": {"bio": "Venom Shah is the academy prodigy made for the Furnace: selfish, relentless, and already snarling at defenders twice his age.", "race": "Ignid (Venus)", "gender": "Male", "culture": "The next hard man.", "species": "ignid", "injuries": "Fully fit.", "appearance": "Lean and ferocious, a teenage striker who presses like a veteran.", "personality": "Selfish and ferocious.", "achievements": ["Youth top scorer"], "political_leaning": "Indifferent."}, "team_id": "venus-volcanic", "position": "FW", "nationality": "Venusian"}$meta$),
    ('a30d1888-9f70-4625-b7fb-2004f1b82e5e', 'fe4b654acc6615098e72202c3606d901', $meta${"profile": {"bio": "Aiko Nakajima is the metronome at the base of midfield, the inheritor of the club's most sacred role. She rarely makes the highlight reels and never wants to; her artistry is in the pass before the pass.", "race": "Human", "gender": "Female", "culture": "The purest expression of the Earth United creed in the current side.", "species": "terran", "injuries": "Fully fit.", "appearance": "Small, balanced, perpetually scanning: a midfielder who seems to see the whole pitch at once.", "personality": "Selfless orchestrator; lives to make others look good.", "achievements": ["Highest pass-completion run in a single season in club records"], "political_leaning": "Disengaged from politics entirely."}, "team_id": "earth-united", "position": "MF", "nationality": "Earthian"}$meta$),
