    ('a9f9269d-9c9c-4204-8560-46596a6b6792', '6761a6bf006938d3a9b5f7d63fda6724', $meta${"profile": {"badge": "An elongated ellipse spinning around a bright core, motion-blurred.", "history": "Haumea Spinners play a giddy, attacking, wide-area game born of their fast-spinning world. They stretch the pitch end to end and side to side, whirling opponents into dizziness with relentless offensive movement. It is exhausting to watch and worse to mark.", "away_kit": "Yellow with white swirls.", "home_kit": "Bright white and electric-yellow with a spiral motion pattern.", "third_kit": "Silver with a blurred-rotation motif.", "achievements": ["Highest-scoring side in the Kuiper Belt"], "club_culture": "Restless, attacking, and dizzyingly energetic. The Whirl never stop moving.", "date_founded": "Founded on fast-spinning, egg-shaped Haumea, where the dizzying rotation shaped a unique wide-area game.", "fans_nickname": "The Whirl", "number_of_fans": "Around 5 million, as restless as their spinning world.", "political_leaning": "Kuiper-frontier libertarian: fast, free, and allergic to being held in place."}, "team_id": "haumea-spinners", "league_id": "kuiper-belt"}$meta$),
    ('aaa81124-4864-4bde-91c2-2129870f66a3', '6437bf67070f01e9a33871d19e3c7d87', $meta${"profile": {"bio": "Sable Torres is the metronome that keeps the Mars Athletic counter from descending into chaos, composed where her teammates are frantic.", "race": "Human (Mars-adapted)", "gender": "Female", "culture": "The steady hand.", "species": "terran", "injuries": "Fully fit.", "appearance": "Even-keeled and tidy, the balance of the midfield.", "personality": "Balanced and unflappable.", "achievements": ["Ever-present in midfield"], "political_leaning": "Martian-nationalist."}, "team_id": "mars-athletic", "position": "MF", "nationality": "Martian"}$meta$),
    ('abb991eb-0d53-41db-86f4-5ba49dfeaaf7', '73dd3c8048372a8ddb4898b121c5aa6d', $meta${"profile": {"bio": "Carlos Ribeiro is the licensed disruptor in a disciplined system, the one player Okafor permits to gamble. When the patient build-up stalls, it is Ribeiro who finds the pass nobody else could see.", "race": "Human", "gender": "Male", "culture": "The spark the institution tolerates because it needs him.", "species": "terran", "injuries": "Fully fit.", "appearance": "Slight and quick-footed, with a magician's flair for the unexpected and an untucked shirt to match.", "personality": "Creative, mercurial, occasionally maddening.", "achievements": ["Assist of the Season, twice voted by the fans"], "political_leaning": "Bohemian; sympathetic to the colonies but allergic to manifestos."}, "team_id": "earth-united", "position": "MF", "nationality": "Earthian"}$meta$),
    ('acd0595f-a6ce-4e99-a42b-2d570323719f', '59abf9a89d331332fbed163b8ff0a374', $meta${"corps": "IEOB", "profile": {"age": 40, "bio": "A fast Haumeian referee, Achernar Sharma is the corps' specialist at the giddy, attacking wide-area game of the Kuiper.", "race": "Human (Kuiper-adapted)", "gender": "Female", "culture": "The whirl-watcher.", "appearance": "Quick and dizzy-proof, keeps up with the whirl.", "nationality": "Haumeian", "personality": "Quick, alert, and tireless.", "achievements": ["Specialist in high-movement fixtures"], "officiating_style": "Movement-ready: never dizzied by the whirl.", "political_leaning": "Kuiper-frontier libertarian."}, "homeworld": "Haumea"}$meta$),
    ('ae6bb1cb-8343-4aa3-b366-c30e3349bfc0', '6abbd55364b517aacd6b75a2046ac167', $meta${"era": "retired_coach", "profile": {"age": 48, "bio": "A retired Mercurian coach obsessed with dead balls, Flare Asante is the leagues' go-to voice on set-piece detail.", "race": "Human (Mercury-adapted)", "gender": "Male", "culture": "The set-piece nerd.", "appearance": "Animated and precise, diagrams set pieces in the air.", "nationality": "Mercurian", "personality": "Animated, meticulous, and slightly obsessive.", "achievements": ["The leagues' set-piece authority"], "playing_history": "A set-piece specialist coach.", "commentary_style": "Detail-obsessed: pauses everything to dissect a corner.", "political_leaning": "Frontier-independent."}, "homeworld": "Mercury", "specialty": "set_pieces"}$meta$),
    ('b06db269-8ee0-4972-82b9-a64e515868b4', 'f782b1056d2a817be8745189af3583e8', $meta${"profile": {"badge": "A jagged star at the far edge of a thin disc, turned away from the sun.", "history": "Eris Wanderers play with the chip-on-the-shoulder defiance of the system's most remote club. Counterattacking specialists who relish the long, lonely journey to every away game, they take grim pleasure in spoiling the parties of warmer, richer worlds.", "away_kit": "Ash-grey with violet shards.", "home_kit": "Deep void-violet and black with a fractured-star motif.", "third_kit": "Near-black with a single distant star.", "achievements": ["Most away points won by a Kuiper side"], "club_culture": "Defiant, hardy, and proudly contrarian. The Discordant exist to disrupt.", "date_founded": "Founded on Eris, the most distant outpost in the leagues, by settlers who chose the edge of everything.", "fans_nickname": "The Discordant", "number_of_fans": "Around 5 million fiercely defiant edge-dwellers.", "political_leaning": "Kuiper-separatist: the loudest voice for the outer worlds' independence."}, "team_id": "eris-wanderers", "league_id": "kuiper-belt"}$meta$),
    ('b46d20c5-a8ac-49ec-8c30-3c7d6abb903f', '1cb13c731690ddc0297fbaa284c76788', $meta${"profile": {"badge": "Two locked moons orbiting a shared point, bound by a silver thread.", "history": "Charon United are a young, balanced side still finding themselves in the long shadow of Pluto. Tidally bound to their larger neighbour, they play steady, organised football and dream of stepping out of the gloom into a light of their own.", "away_kit": "Dark slate with a single silver thread.", "home_kit": "Pale grey and silver with a binary-orbit motif.", "third_kit": "Twilight blue with twin discs.", "achievements": ["Fastest-developing youth setup in the Kuiper Belt"], "club_culture": "Earnest, developing, and quietly ambitious. The Twins are still writing their story.", "date_founded": "Founded on Charon, forever locked face-to-face with Pluto, a young club still carving out an identity of its own.", "fans_nickname": "The Twins", "number_of_fans": "Around 6 million, devoted dwellers of the binary world.", "political_leaning": "Kuiper-autonomist: a small world seeking its own voice."}, "team_id": "charon-united", "league_id": "kuiper-belt"}$meta$),
    ('b8e1edaf-a5d0-482d-84ea-3baf55699935', '2044ce1912aec7589c23eddc9a01a154', $meta${"profile": {"bio": "Relay Santos is the all-action midfielder who embodies the club's flexibility: defending, creating, and arriving late in the box.", "race": "Orbital Colonist", "gender": "Male", "culture": "The complete midfielder.", "species": "terran", "injuries": "Fully fit.", "appearance": "Balanced and box-to-box, comfortable everywhere.", "personality": "Balanced and busy.", "achievements": ["Most midfield goals"], "political_leaning": "Frontier Coalition."}, "team_id": "solar-city", "position": "MF", "nationality": "Orbital Colonist"}$meta$),
    ('bd7e3ccf-26af-49a2-97fa-04c33b3c223b', '73dbcc4dd7b4afbdb46ba2e0159aa71f', $meta${"profile": {"badge": "A ball arcing high over a cratered protoplanet horizon.", "history": "Vesta are masters of low-gravity football: a direct side that launches long, floating balls into the great open spaces the weak gravity creates. It looks strange to outsiders and works beautifully for the Floaters.", "away_kit": "White with blue trim and a faint crater pattern.", "home_kit": "Pale silver and sky-blue with a high-arc trajectory motif.", "third_kit": "Deep space-blue with a luminous arc.", "achievements": ["Most goals from direct, long-ball play in the belt"], "club_culture": "Inventive, proud, and at home in the low gravity. The Floaters embrace what makes their world different.", "date_founded": "Founded on the protoplanet Vesta, where the punishing low gravity shaped a unique long-ball game.", "fans_nickname": "The Floaters", "number_of_fans": "Around 16 million, devoted to their gravity-defying side.", "political_leaning": "Belt frontier-pragmatist: practical, independent, and quietly inventive."}, "team_id": "vesta", "league_id": "outer-reaches"}$meta$),
    ('c0a3900c-6adf-44d8-abc8-194d0f630f23', '80f0c4aea0ef160342ca94bb6b161ae4', $meta${"corps": "IEOB", "profile": {"age": 43, "bio": "A no-nonsense Cerean referee, Polaris Mensah commands respect in the gritty, hard-fought belt fixtures.", "race": "Human (Belt-adapted)", "gender": "Female", "culture": "The belt's whistle.", "appearance": "Tough and direct, a belt official to the core.", "nationality": "Cerean", "personality": "Tough, direct, and respected.", "achievements": ["Trusted with the fiercest belt derbies"], "officiating_style": "Firm and direct: keeps the belt's games honest.", "political_leaning": "Belt old-frontier."}, "homeworld": "Ceres"}$meta$),
    ('c1295414-a909-4149-8495-530ef3a9bd2d', '14f1e82d44155bc12ce44240ae2c9428', $meta${"corps": "IEOB", "profile": {"age": 42, "bio": "A perceptive Titanian referee, Capella Rivera keeps control of the hazy, ambush-prone matches of her home moon.", "race": "Human (Titan-adapted)", "gender": "Female", "culture": "The vigilant eye.", "appearance": "Watchful and inscrutable, comfortable in the murk.", "nationality": "Titanian", "personality": "Watchful, patient, and guarded.", "achievements": ["Trusted with low-tempo, ambush-style fixtures"], "officiating_style": "Vigilant: never lulled by a quiet game.", "political_leaning": "Frontier-independent."}, "homeworld": "Titan"}$meta$),
    ('c3ee82d5-9bf5-4fdb-a37c-1a25d978ae64', '060ad6387e3821e0da467bd6118b8bbc', $meta${"profile": {"bio": "Sophie Hartmann is the snarl in an otherwise gentle side. A full-back who treats the touchline as a personal border to be defended at all costs, she gives the patient Old Worlders the edge of aggression they would otherwise lack.", "race": "Human", "gender": "Female", "culture": "A scrapper who respects effort above pedigree.", "species": "terran", "injuries": "Fully fit; carries a long-managed ankle that flares in cold domes.", "appearance": "Lean and sharp-featured, hair cropped short, always the first into a challenge and the last to back out of one.", "personality": "Fiery and confrontational, walks the line of the referee's patience.", "achievements": ["Most fan-voted tackles of the season, twice"], "political_leaning": "Outspoken Frontier Coalition supporter, unusual in this dressing room."}, "team_id": "earth-united", "position": "DF", "nationality": "Earthian"}$meta$),
    ('c741aebe-69f6-4745-81d9-0abb12ca1bdc', '24e5b7b2ef8491828382a6a2b3d55e37', $meta${"profile": {"badge": "A lone figure walking toward a distant asteroid horizon.", "history": "Pallas Wanderers have no fixed identity and make a virtue of it: a balanced, adaptable side that shifts its approach to suit any opponent. Rootless and flexible, they are nobody's easy game.", "away_kit": "Faded ochre with brown trim.", "home_kit": "Sand-tan and brown with a drifting-dune pattern.", "third_kit": "Dusk-purple with a wandering-trail motif.", "achievements": ["Most tactically varied side in the belt"], "club_culture": "Restless, adaptable, and self-reliant. The Drifters belong to no one and adjust to everyone.", "date_founded": "Founded by the roving prospector crews of Pallas, who never stayed in one crater for long.", "fans_nickname": "The Drifters", "number_of_fans": "Around 12 million, scattered and wandering like the club itself.", "political_leaning": "Belt free-prospector: fiercely independent and suspicious of all authority."}, "team_id": "pallas-wanderers", "league_id": "outer-reaches"}$meta$),
    ('c875c153-911a-4b00-9bb6-806c08ad1573', 'ef3b59c7122afe07ba0b533e039a9407', $meta${"profile": {"age": 48, "bio": "Ignis Ferrara is fury with a clipboard: a former hard-man midfielder who builds teams in his own image. His aggressive, high-tempo football is designed to make opponents crack, and his touchline conduct is a legend (and a liability) in its own right.", "race": "Human (Venus-adapted)", "gender": "Male", "culture": "A son of the pressure domes who treats every match as a grievance to settle.", "appearance": "Stocky and seething, prowls the technical area like a man looking for an argument.", "nationality": "Venusian", "personality": "Volatile, combative, and utterly fearless.", "achievements": ["Turned a modest squad into the league's most feared pressing side"], "playing_history": "A notoriously aggressive midfield destroyer, more cards than goals.", "political_leaning": "Venusian hardline-militant.", "playing_philosophy": "Make them hate every minute. Press, provoke, and pounce on the mistakes that pressure always produces."}, "team_id": "venus-volcanic", "game_model": {"tempo": "vertical", "width": "balanced", "onLoss": "counterpress", "onRegain": "counter", "restShape": "3+2", "blockWidth": 40, "blockHeight": "high", "blockLength": 32, "restDefence": 5, "buildUpShape": "3-2-5", "fullBackRole": "overlap", "pressTriggers": ["always"], "lineManagement": "aggressive", "counterpressSec": 6, "settledLineHeight": 38, "counterpressPlayers": 3}, "nationality": "Venusian"}$meta$),
    ('c9415a50-dce5-4056-a5c3-6335f54a5f9d', '486be5425a82afa479e972d028cc643b', $meta${"corps": "IEOB", "profile": {"age": 39, "bio": "A composed Makean referee, Regulus Torres is well-matched to the patient, creative football of her home world.", "race": "Human (Kuiper-adapted)", "gender": "Female", "culture": "The patient official.", "appearance": "Calm and patient, suits the possession game.", "nationality": "Makean", "personality": "Calm, patient, and fair.", "achievements": ["Specialist in possession-based fixtures"], "officiating_style": "Flow-friendly: lets the creative game develop.", "political_leaning": "Kuiper-communalist."}, "homeworld": "Makemake"}$meta$),
    ('c942f118-c00d-4b0f-bbab-b48ea94ed6ee', '4d7fadd032c3751b20e6dae50deb8e30', $meta${"corps": "IEOB", "profile": {"age": 47, "bio": "A no-nonsense Venusian referee, Deneb Asante handles the leagues' most heated, aggressive fixtures without flinching.", "race": "Human (Venus-adapted)", "gender": "Male", "culture": "The hard-match specialist.", "appearance": "Hard-faced and combative, gives as good as he gets.", "nationality": "Venusian", "personality": "Tough, combative, and fearless.", "achievements": ["Trusted with the most volatile fixtures"], "officiating_style": "Firm in the storm: built for hostile, physical games.", "political_leaning": "Venusian hardline."}, "homeworld": "Venus"}$meta$),
    ('cb48dab0-4709-45cd-8ca9-afa3e314bf59', '536d3f55be1b52d06e1a1489de5c070e', $meta${"profile": {"badge": "A balanced civic scale over a stylised city skyline.", "history": "Juno City are the belt's disciplinarians: a balanced, organised side that values structure and tactical order above all. They rarely beat themselves, and that, in the chaotic belt, is half the battle won.", "away_kit": "White with purple trim and a thin skyline silhouette.", "home_kit": "Royal purple and white with a clean geometric city-grid pattern.", "third_kit": "Slate with luminous grid lines.", "achievements": ["Fewest cards and most disciplined record in the belt"], "club_culture": "Orderly, civic-minded, and tactically disciplined. The Civics believe in doing things properly.", "date_founded": "Founded as the civic pride of Juno, the belt's most orderly and well-governed settlement.", "fans_nickname": "The Civics", "number_of_fans": "Around 17 million orderly, organised supporters.", "political_leaning": "Belt civic-institutionalist: the belt's voice of law and order."}, "team_id": "juno-city", "league_id": "outer-reaches"}$meta$),
    ('cb8562a9-661e-45c6-85d7-8a8358b008b6', 'cb329b2de9a82e3f6acc3c2389a74c3d', $meta${"profile": {"badge": "An open hand cupping a newborn star, rays spreading outward.", "history": "Makemake are the Kuiper's artists, a possession side famed for conjuring chances from nothing on a shoestring budget. Where others see a dead end, the Makers thread a pass; their creative, patient football is a small miracle at the edge of the system.", "away_kit": "Cream with terracotta sunburst.", "home_kit": "Warm terracotta and cream with a creation-ray motif.", "third_kit": "Deep earth-red with a single newborn star.", "achievements": ["Most chances created per budget credit in the Kuiper"], "club_culture": "Creative, devout, and resourceful. The Makers believe football is an act of creation.", "date_founded": "Founded on Makemake, named for a creator-deity, by settlers who prized making something from nothing.", "fans_nickname": "The Makers", "number_of_fans": "Around 4 million faithful, devoted to the club's creative gospel.", "political_leaning": "Kuiper-communalist: a co-operative club that shares everything it has."}, "team_id": "makemake", "league_id": "kuiper-belt"}$meta$),
    ('cd4c50f9-3bfa-4c80-a0f0-4cfe7e6164c8', 'd09c904af1d40551c8ca0127ff74b493', $meta${"corps": "IEOB", "profile": {"age": 43, "bio": "An elegant Saturnian referee, Altair Nakamura officiates with a light touch that suits the ring-world's beautiful game.", "race": "Human (Saturn-adapted)", "gender": "Female", "culture": "The light touch.", "appearance": "Graceful and unobtrusive, lets the beauty flow.", "nationality": "Saturnian", "personality": "Graceful, light-touch, and fair.", "achievements": ["Favoured for showpiece fixtures"], "officiating_style": "Unobtrusive: referees to let football breathe.", "political_leaning": "Saturnian old-aristocracy."}, "homeworld": "Saturn"}$meta$),
