    ('ce1589ab-d320-448d-aee1-23baa499a8db', 'e21b2f09891c2a74851b891397c9c7a8', $meta${"era": "retired_player", "profile": {"age": 44, "bio": "A beloved retired forward, Stellar Cruz brings warmth and sharp generalist insight to GSN's flagship coverage.", "race": "Human", "gender": "Female", "culture": "The fans' favourite.", "appearance": "Warm and quick-witted, the studio's most likeable presence.", "nationality": "Earthian", "personality": "Warm, witty, and disarmingly sharp.", "achievements": ["Most popular pundit by fan vote"], "playing_history": "A popular former forward.", "commentary_style": "Accessible and warm: explains the game to everyone.", "political_leaning": "Apolitical and proud of it."}, "homeworld": "Earth", "specialty": "general"}$meta$),
    ('d110e555-f943-4dc6-bffb-788878b64040', '43d7e31874e739d51aa86ea3ed9a8f50', $meta${"profile": {"badge": "A pale blue marble cradled between two crossed comet-tails, ringed by eleven stars: one for each of the founding players who first took the pitch.", "history": "Earth United are the keepers of the game's oldest memory. Before the leagues reached the gas giants or the belt was ever settled, the Old Worlders were already playing the patient, passing football that every rival has since tried to copy or kill. They have known dynasties and droughts in equal measure, but the club's identity has never wavered: the ball is sacred, possession is virtue, and the institution outlives any one star.", "away_kit": "Bone white with royal-blue trim and a faint topographic map of the old continents printed across the chest.", "home_kit": "Royal blue shirt, white shorts, white socks. A thin silver meridian line runs from collar to hem.", "third_kit": "Deep midnight navy flecked with starfield silver, worn for cup nights and remembrance fixtures.", "achievements": ["Oldest charter never to have been relegated from the top flight", "Architects of the possession style now taught system-wide"], "club_culture": "Institutional and proud to the point of stubbornness. Earth United believe football should be earned through patience, not stolen through chaos, a worldview that makes them beloved by purists and insufferable to everyone else.", "date_founded": "First Season of the League Era: the oldest continuous charter in the Rocky Inner League.", "fans_nickname": "The Old Worlders", "number_of_fans": "Around 40 million, scattered across Earth and her orbital colonies.", "political_leaning": "Solaris Compact establishment. The club of the old order, courted by every inner-system politician who wants to look respectable."}, "team_id": "earth-united", "league_id": "rocky-inner"}$meta$),
    ('d3654886-5e5c-415b-84a2-b1543142b369', '65f34b201726f1df196ea52fa8999f76', $meta${"profile": {"age": 54, "bio": "Patient Okonkwo is the apostle of waiting: a defensive purist whose Mariners sit deep, give nothing away, and strike only when the long game finally tilts. He has out-waited far quicker, far richer sides.", "race": "Human (Kuiper-adapted)", "gender": "Male", "culture": "A monk of the long game.", "appearance": "Serene and unhurried, watches matches with monastic stillness.", "nationality": "Sednan", "personality": "Serene, disciplined, and immovably patient.", "achievements": ["Built the Kuiper's most miserly defence"], "playing_history": "A sweeper who read the game so well he rarely needed to rush.", "political_leaning": "Kuiper-isolationist.", "playing_philosophy": "Wait. Defend, endure, and the moment will come. Patience is the deadliest tactic."}, "team_id": "sedna-mariners", "game_model": {"tempo": "patient", "width": "narrow", "onLoss": "recover", "onRegain": "secure", "restShape": "4+2", "blockWidth": 34, "blockHeight": "low", "blockLength": 26, "restDefence": 6, "buildUpShape": "4-2-4", "fullBackRole": "stay", "pressTriggers": ["bad_touch"], "lineManagement": "cautious", "counterpressSec": 3, "settledLineHeight": 25, "counterpressPlayers": 1}, "nationality": "Sednan"}$meta$),
