    ('dc54da0b-fffa-4ed6-a89e-bd6d0b54993c', 'aa45aa3f506873139f025a6979d57276', $meta${"profile": {"badge": "A bright orbital ring encircling a central sun, studded with stars for every world that built the colony.", "history": "Solar City are the cosmopolitans of the league: a club assembled, like their colony, from every corner of the system. They play balanced, adaptable football and pride themselves on having no single style, only the flexibility to meet any opponent. They are the future the inner worlds are nervous about.", "away_kit": "Sky-blue with a silver ring, light as the colony's open habitats.", "home_kit": "Gold and white with a thin orbital ring sweeping across the chest.", "third_kit": "Black with a luminous ring that glows under the stadium lights.", "achievements": ["Most nationalities ever fielded in a single match", "Fastest-rising club of the modern era"], "club_culture": "Open, progressive, and endlessly adaptable. The Ringers believe diversity is a tactical advantage, not a slogan.", "date_founded": "Founded in the boom years of the great orbital colony, by settlers from a dozen worlds who wanted a club of their own.", "fans_nickname": "The Ringers", "number_of_fans": "Around 30 million, the most diverse fanbase in the system.", "political_leaning": "Frontier Coalition cosmopolitan: the flagship club of the colonies' rising confidence."}, "team_id": "solar-city", "league_id": "rocky-inner"}$meta$),
