    ('ddfc5c54-7ac2-44e5-bc18-b18fb8c1524d', '4bf7bd6bc39693c35f6a978b3e439417', $meta${"profile": {"badge": "A white geyser bursting from blue ice toward a ringed sky.", "history": "Enceladus Geysers do one thing spectacularly: they erupt. A modest, youthful side with little money, they sit deep, absorb pressure, and then explode forward in sudden, devastating counters that have humbled far richer clubs.", "away_kit": "White with blue trim and a single erupting plume.", "home_kit": "Pale ice-blue with white spray streaks rising from the hem.", "third_kit": "Deep ocean teal flecked with frost-white.", "achievements": ["Most goals scored on the counter in the league"], "club_culture": "Patient then explosive, and proud of their underdog status. The Eruption love nothing more than ambushing a giant.", "date_founded": "Founded by the research outposts clustered around Enceladus's great geysers, a young and scrappy club.", "fans_nickname": "The Eruption", "number_of_fans": "Around 11 million, small in number but explosive in voice.", "political_leaning": "Frontier-independent, with the open-minded streak of a research colony."}, "team_id": "enceladus-geysers", "league_id": "gas-giants"}$meta$),
