    ('e15364a7-4d55-4cff-8486-96bc4405b7d1', '64462452e2b81d606ae8a679a5710456', $meta${"profile": {"badge": "A single ship on a vast, slow elliptical voyage around a faint sun.", "history": "Sedna Mariners are the most patient team in the system: a defensive, glacial side that waits, and waits, and waits for the one moment a match turns. Raised on the longest orbit known, they have made patience itself a philosophy, and it drives quicker opponents to despair.", "away_kit": "Pale stone with a thin maroon arc.", "home_kit": "Deep maroon and slate with a long-orbit ellipse motif.", "third_kit": "Midnight maroon with a faint distant sun.", "achievements": ["Fewest goals conceded per match in the Kuiper"], "club_culture": "Patient, monkish, and serenely stubborn. The Patient believe time itself is their twelfth player.", "date_founded": "Founded on Sedna, whose orbit takes millennia, by settlers who learned that everything worth having takes time.", "fans_nickname": "The Patient", "number_of_fans": "Around 4 million, as unhurried and devoted as their distant world.", "political_leaning": "Kuiper-isolationist: distant, self-contained, and in no hurry to change."}, "team_id": "sedna-mariners", "league_id": "kuiper-belt"}$meta$),
